create extension if not exists pgcrypto;create table if not exists public.payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,vendor text not null,payment_date date not null,mode text not null,purpose text not null,amount numeric(14,2) not null check(amount>=0),created_at timestamptz default now(),updated_at timestamptz default now());create index if not exists payments_user_date_idx on public.payments(user_id,payment_date desc);alter table public.payments enable row level security;drop policy if exists "own_select" on public.payments;drop policy if exists "own_insert" on public.payments;drop policy if exists "own_update" on public.payments;drop policy if exists "own_delete" on public.payments;create policy "own_select" on public.payments for select using(auth.uid()=user_id);create policy "own_insert" on public.payments for insert with check(auth.uid()=user_id);create policy "own_update" on public.payments for update using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own_delete" on public.payments for delete using(auth.uid()=user_id);
